"""Source-free frame perception helpers for cracking.

This module is deliberately observational: it derives compact symbolic state
from `env.frame()` and `env.clone()` only. It is a cofibration-style scaffold:
raw pixels are embedded into a monotone tower of reusable observations
(components -> objects -> action deltas -> replay states). Candidate level
logic should be written against these quotients, then replay-validated by the
harness. No game source or prior solution history is read here.
"""
from collections import deque
from dataclasses import dataclass
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

import numpy as np

UP, DOWN, LEFT, RIGHT, USE = 1, 2, 3, 4, 5
ACTIONS = (UP, DOWN, LEFT, RIGHT, USE)
DIRS = {UP: (-1, 0), DOWN: (1, 0), LEFT: (0, -1), RIGHT: (0, 1)}
ACTION_NAME = {UP: "UP", DOWN: "DOWN", LEFT: "LEFT", RIGHT: "RIGHT", USE: "USE"}


@dataclass(frozen=True)
class Blob:
    color: int
    bbox: Tuple[int, int, int, int]  # r0, c0, r1, c1 inclusive
    area: int
    centroid: Tuple[float, float]

    @property
    def top_left(self):
        return self.bbox[0], self.bbox[1]

    @property
    def size(self):
        r0, c0, r1, c1 = self.bbox
        return r1 - r0 + 1, c1 - c0 + 1


def arr(frame) -> np.ndarray:
    return np.asarray(frame)


def color_counts(frame) -> Dict[int, int]:
    vals, cnts = np.unique(arr(frame), return_counts=True)
    return {int(v): int(c) for v, c in zip(vals, cnts)}


def connected_components(frame, colors: Optional[Iterable[int]] = None,
                         min_area: int = 1) -> List[Blob]:
    f = arr(frame)
    wanted = None if colors is None else {int(c) for c in colors}
    seen = np.zeros(f.shape, dtype=bool)
    out: List[Blob] = []
    rows, cols = f.shape[:2]
    for r in range(rows):
        for c in range(cols):
            if seen[r, c]:
                continue
            color = int(f[r, c])
            if wanted is not None and color not in wanted:
                seen[r, c] = True
                continue
            q = [(r, c)]
            seen[r, c] = True
            pts = []
            while q:
                x, y = q.pop()
                pts.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < rows and 0 <= ny < cols and not seen[nx, ny] and int(f[nx, ny]) == color:
                        seen[nx, ny] = True
                        q.append((nx, ny))
            if len(pts) >= min_area:
                rs = [p[0] for p in pts]
                cs = [p[1] for p in pts]
                out.append(Blob(color, (min(rs), min(cs), max(rs), max(cs)),
                                len(pts), (sum(rs) / len(pts), sum(cs) / len(pts))))
    return sorted(out, key=lambda b: (b.color, b.bbox))


def block_signatures(frame, cell: int = 4) -> Dict[Tuple[int, int], Tuple[int, ...]]:
    """Partition a frame into fixed cells and return each cell's color signature."""
    f = arr(frame)
    out = {}
    for r in range(0, f.shape[0], cell):
        for c in range(0, f.shape[1], cell):
            out[(r // cell, c // cell)] = tuple(int(v) for v in sorted(np.unique(f[r:r+cell, c:c+cell])))
    return out


def object_candidates(frame, cell: int = 4, min_area: int = 4) -> List[dict]:
    """A compact, game-agnostic object list from color components and cell signatures."""
    f = arr(frame)
    blobs = connected_components(f, min_area=min_area)
    sigs = block_signatures(f, cell)
    objects = []
    for b in blobs:
        r0, c0, r1, c1 = b.bbox
        objects.append({
            "color": b.color,
            "bbox": b.bbox,
            "top_left": b.top_left,
            "size": b.size,
            "area": b.area,
            "centroid": b.centroid,
            "cell": (r0 // cell, c0 // cell),
            "cell_sig": sigs.get((r0 // cell, c0 // cell)),
        })
    return objects


def frame_delta(before, after) -> dict:
    a, b = arr(before), arr(after)
    ys, xs = np.where(a != b)
    if len(ys) == 0:
        return {"count": 0, "bbox": None, "samples": []}
    samples = [(int(y), int(x), int(a[y, x]), int(b[y, x])) for y, x in zip(ys[:80], xs[:80])]
    return {
        "count": int(len(ys)),
        "bbox": (int(ys.min()), int(xs.min()), int(ys.max()), int(xs.max())),
        "samples": samples,
    }


def normalize_public_action(action):
    """Validate one public key or coordinate action without touching ``env``."""
    if isinstance(action, (list, tuple)):
        if (
            len(action) != 3
            or action[0] != 6
            or any(
                not isinstance(value, int) or isinstance(value, bool)
                for value in action
            )
        ):
            raise ValueError(
                "coordinate action must be (6, x, y) with integer x,y in 0..63"
            )
        normalized = (6, int(action[1]), int(action[2]))
        if not (0 <= normalized[1] < 64 and 0 <= normalized[2] < 64):
            raise ValueError(
                "coordinate action must be (6, x, y) with integer x,y in 0..63"
            )
        return normalized
    if (
        not isinstance(action, int)
        or isinstance(action, bool)
        or action not in range(1, 8)
    ):
        raise ValueError("key action must be an integer in 1..7")
    if action == 6:
        raise ValueError(
            "bare ACTION6 is invalid; use (6, x, y) with integer x,y in 0..63"
        )
    return int(action)


def safe_step(env, action):
    """Validate locally, then apply one public key or coordinate action."""
    normalized = normalize_public_action(action)
    if isinstance(normalized, tuple):
        env.step(*normalized)
    else:
        env.step(normalized)
    return normalized


def action_deltas(env, actions=None) -> Dict[object, dict]:
    """Compare valid cloned actions; bare ACTION6 is never sent to the arena."""
    if actions is None:
        actions = tuple(action for action in env.actions if action != 6)
    normalized_actions = tuple(
        normalize_public_action(action) for action in actions
    )
    base = arr(env.frame()).copy()
    out = {}
    for action in normalized_actions:
        clone = env.clone()
        safe_step(clone, action)
        out[action] = frame_delta(base, clone.frame())
    return out


def replay(env, actions: Sequence):
    normalized_actions = tuple(
        normalize_public_action(action) for action in actions
    )
    clone = env.clone()
    for action in normalized_actions:
        if clone.terminal():
            break
        safe_step(clone, action)
    return clone


def path_result(env, actions: Sequence[int]) -> dict:
    clone = replay(env, actions)
    return {
        "levels_completed": int(clone.levels_completed),
        "terminal": bool(clone.terminal()),
        "path_len": len(actions),
        "colors": color_counts(clone.frame()),
        "objects": object_candidates(clone.frame()),
    }
"""Reusable skills inferred from public frames and clone experiments."""
from perception import arr, connected_components, safe_step


def align_marked_bar_tips(env, max_moves=40):
    """Click paired controls to bring coloured bar tips onto cross marks.

    Crosses are four pink pixels around an empty centre; the moving tips
    are pink too. Choose controls by their measured reduction in distance.
    """
    frame = arr(env.frame())
    marks = []
    for y in range(1, 63):
        for x in range(1, 63):
            if frame[y, x] == 5 and all(
                frame[y + dy, x + dx] == 13
                for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1))
            ):
                marks.append((x, y))
    controls = []
    for blob in connected_components(frame, colors=[4], min_area=4):
        y0, x0, y1, x1 = blob.bbox
        controls.append((6, (x0 + x1) // 2, (y0 + y1) // 2))
    if not marks or not controls:
        return
    cross_pixels = {
        (x + dx, y + dy)
        for x, y in marks
        for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1))
    }

    def distance(candidate):
        pixels = arr(candidate.frame())
        ys, xs = (pixels == 13).nonzero()
        tips = [(int(x), int(y)) for y, x in zip(ys, xs)
                if (int(x), int(y)) not in cross_pixels]
        # A tip must serve its own mark; nearest-tip sums can strand a
        # distant tip when another tip is close to both marks.
        costs = {0: 0}
        for x, y in marks:
            following = {}
            for mask, cost in costs.items():
                for i, (tx, ty) in enumerate(tips):
                    if not mask & (1 << i):
                        key = mask | (1 << i)
                        value = cost + abs(x - tx) + abs(y - ty)
                        following[key] = min(following.get(key, 10000), value)
            costs = following
        return min(costs.values(), default=10000)

    level = env.levels_completed
    for _ in range(max_moves):
        if env.terminal() or env.levels_completed > level:
            return

        best_action = None
        best_score = distance(env)
        for action in controls:
            clone = env.clone()
            safe_step(clone, action)
            if clone.levels_completed > level:
                best_action = action
                break
            score = distance(clone)
            if score < best_score:
                best_action, best_score = action, score
        if best_action is None:
            return
        safe_step(env, best_action)


def park_crossing_telescopic_barriers(env, max_moves=60, stages=None):
    """Park coupled horizontal/vertical barriers outside crossing tip lanes.

    First separate the carriers sideways and upward, then retract the
    perpendicular carriers. Saturate each joint using observed geometry,
    verifying the complete parking sequence on a clone before committing.
    Optional (colour, side, click_limit) stages permit separated parking lanes.
    """
    import numpy as np

    frame = arr(env.frame())
    controls = {}
    buttons = connected_components(frame, colors=[4], min_area=4)
    if not buttons:
        return
    ui_top = min(b.bbox[0] for b in buttons) - 1
    for blob in buttons:
        y0, x0, y1, x1 = blob.bbox
        glyph = frame[y0:y1 + 1, x0:x1 + 1]
        colors, counts = np.unique(glyph[glyph != 4], return_counts=True)
        if len(colors):
            color = int(colors[counts.argmax()])
            controls.setdefault(color, []).append((6, (x0+x1)//2, (y0+y1)//2))
    if stages is None:
        stages = ((9, 1, 16), (14, 1, 16), (8, 0, 16), (12, 0, 16))
    if any(len(controls.get(color, [])) != 2 for color, _, _ in stages):
        return
    clone = env.clone()
    path = []
    for color, side, click_limit in stages:
        action = sorted(controls[color], key=lambda a: a[1])[side]
        for _ in range(click_limit):
            before = arr(clone.frame())[:ui_top].copy()
            safe_step(clone, action)
            if np.array_equal(before, arr(clone.frame())[:ui_top]):
                break
            path.append(action)
            if len(path) > max_moves:
                return
    for action in path:
        safe_step(env, action)


def route_telescoping_arm_through_gap(env, max_moves=100):
    """Route a right/up/right/down arm via clear, grid-aligned bends.

    Derive candidate bends from the visible arm and obstacles. Verify each
    complete staged extension on a clone before committing its control clicks.
    """
    from perception import replay

    frame = arr(env.frame())
    controls = []
    for blob in connected_components(frame, colors=[4], min_area=4):
        y0, x0, y1, x1 = blob.bbox
        controls.append((6, (x0 + x1) // 2, (y0 + y1) // 2))
    controls.sort(key=lambda action: action[1])
    if len(controls) != 8:
        return
    ui_top = min(action[2] for action in controls) - 3
    parts = {}
    for blob in connected_components(frame, colors=[12, 10, 11, 14]):
        if blob.bbox[2] < ui_top:
            parts[blob.color] = blob.bbox
    if len(parts) != 4:
        return
    marks = []
    cross_pixels = set()
    for y in range(1, ui_top):
        for x in range(1, 63):
            ring = [(x + dx, y + dy)
                    for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1))]
            if frame[y, x] == 5 and all(frame[py, px] == 13 for px, py in ring):
                marks.append((x, y))
                cross_pixels.update(ring)
    if len(marks) != 1:
        return
    tips = [(int(x), int(y)) for y, x in zip(*(frame == 13).nonzero())
            if y < ui_top and (int(x), int(y)) not in cross_pixels]
    if len(tips) != 1:
        return
    target_x, target_y = marks[0]
    tip_x, tip_y = tips[0]
    base_y = (parts[12][0] + parts[12][2]) // 2
    base_x = parts[12][1] - 1
    joint_x = (parts[10][1] + parts[10][3]) // 2
    joint_y = (parts[11][0] + parts[11][2]) // 2
    unit = parts[10][3] - parts[10][1] + 1
    radius = unit // 2

    def clear(x0, y0, x1, y1):
        return (0 <= x0 <= x1 < 64 and 0 <= y0 <= y1 < ui_top
                and not (frame[y0:y1 + 1, x0:x1 + 1] == 15).any())

    candidates = []
    for bend_x in range(joint_x, target_x, unit):
        for bend_y in range(joint_y, 0, -unit):
            shifted_tip_x = tip_x + bend_x - joint_x
            shifted_tip_y = tip_y + bend_y - joint_y
            changes = (bend_x - joint_x, joint_y - bend_y,
                       target_x - shifted_tip_x, target_y - shifted_tip_y)
            if any(value < 0 or value % unit for value in changes):
                continue
            if not all((
                clear(base_x, base_y - radius, bend_x + radius, base_y + radius),
                clear(bend_x - radius, bend_y - radius, bend_x + radius, base_y + radius),
                clear(bend_x - radius, bend_y - radius, target_x + radius, bend_y + radius),
                clear(target_x - radius, bend_y - radius, target_x + radius, target_y + radius),
            )):
                continue
            path = [controls[2 * i + 1] for i, delta in enumerate(changes)
                    for _ in range(delta // unit)]
            if len(path) <= max_moves:
                candidates.append(path)
    level = env.levels_completed
    for path in sorted(candidates, key=len)[:12]:
        clone = replay(env, path)
        if clone.levels_completed > level:
            for action in path:
                if env.terminal() or env.levels_completed > level:
                    return
                safe_step(env, action)
            return
# Per-level players only compose reusable legs.
from legs import (align_marked_bar_tips, route_telescoping_arm_through_gap,
                  park_crossing_telescopic_barriers)


def play_level_1(env):
    align_marked_bar_tips(env)


def play_level_2(env):
    route_telescoping_arm_through_gap(env)


def play_level_3(env):
    park_crossing_telescopic_barriers(env)
    align_marked_bar_tips(env)


def play_level_4(env):
    park_crossing_telescopic_barriers(
        env, stages=((14, 1, 4), (9, 1, 4), (12, 0, 7), (8, 1, 4)))
    align_marked_bar_tips(env)
import players

def solve(env):
    # dispatch to the per-level player for the current level, in a loop
    while not env.terminal():
        k = env.levels_completed + 1
        fn = getattr(players, f'play_level_{k}', None)
        if fn is None:
            return
        before = env.levels_completed
        fn(env)
        if env.levels_completed <= before:
            return  # no progress -> stop
